import { MINT_EXPORT_ASSETS_PREFIX, MINTLIFY_ICONS_CDN_URL, fromMintExportAssetPath, getLanguageIconUrl, toMintExportAssetPath, } from '@mintlify/common';
import fse from 'fs-extra';
import path from 'path';
import { fetchPublicAsset } from './export-fetch.js';
const ASSET_PATH_PATTERN = new RegExp(`${MINT_EXPORT_ASSETS_PREFIX.replace(/\//g, '\\/')}\\/[A-Za-z0-9._~\\-/%+@]+`, 'g');
const CSS_URL_PATTERN = /url\(\s*(['"]?)([^'")]+)\1\s*\)/g;
const CODE_LANGUAGE_PATTERN = /\slanguage="([^"]+)"/g;
const CONCURRENCY = 10;
const isLanguageIcon = (url) => url.startsWith(`${MINTLIFY_ICONS_CDN_URL}/devicon/`);
export async function* walkFiles(dir) {
    for (const entry of await fse.readdir(dir, { withFileTypes: true })) {
        const entryPath = path.join(dir, entry.name);
        if (entry.isDirectory()) {
            yield* walkFiles(entryPath);
        }
        else if (entry.isFile()) {
            yield entryPath;
        }
    }
}
export async function collectAssetPaths(exportDir) {
    const assetPaths = new Set();
    for await (const file of walkFiles(exportDir)) {
        if (!file.endsWith('.html'))
            continue;
        const html = await fse.readFile(file, 'utf8');
        for (const match of html.matchAll(ASSET_PATH_PATTERN)) {
            assetPaths.add(match[0]);
        }
        for (const [, language = ''] of html.matchAll(CODE_LANGUAGE_PATTERN)) {
            const iconUrl = getLanguageIconUrl(language);
            if (iconUrl)
                assetPaths.add(toMintExportAssetPath(iconUrl));
        }
    }
    return assetPaths;
}
const resolveOutputPath = (exportDir, assetPath) => {
    let decoded;
    try {
        decoded = decodeURIComponent(assetPath);
    }
    catch {
        return undefined;
    }
    const segments = decoded.split(/[\\/]/);
    if (segments.some((segment) => segment === '..' || segment === '.'))
        return undefined;
    const assetsDir = path.resolve(exportDir, `.${MINT_EXPORT_ASSETS_PREFIX}`);
    const outputPath = path.resolve(exportDir, `.${decoded}`);
    return outputPath.startsWith(assetsDir + path.sep) ? outputPath : undefined;
};
const isCss = (url, contentType) => !!contentType?.includes('text/css') || new URL(url).pathname.endsWith('.css');
export function rewriteCssUrls(css, cssUrl, cssAssetPath, onAsset) {
    return css.replace(CSS_URL_PATTERN, (match, quote, rawUrl) => {
        if (rawUrl.startsWith('data:') || rawUrl.startsWith('#'))
            return match;
        if (!cssUrl && rawUrl.startsWith('/') && !rawUrl.startsWith('//')) {
            return `url(${quote}${path.posix.relative(path.posix.dirname(cssAssetPath), rawUrl)}${quote})`;
        }
        let absoluteUrl;
        try {
            absoluteUrl = new URL(rawUrl.startsWith('//') ? `https:${rawUrl}` : rawUrl, cssUrl).toString();
        }
        catch {
            return match;
        }
        const assetPath = toMintExportAssetPath(absoluteUrl);
        if (assetPath === absoluteUrl)
            return match;
        onAsset(assetPath);
        const relativePath = path.posix.relative(path.posix.dirname(cssAssetPath), assetPath);
        return `url(${quote}${relativePath}${quote})`;
    });
}
async function localizeStylesheets(exportDir, onAsset) {
    const nextStaticDir = path.join(exportDir, '_next', 'static');
    if (!(await fse.pathExists(nextStaticDir)))
        return;
    for await (const file of walkFiles(nextStaticDir)) {
        if (!file.endsWith('.css'))
            continue;
        const css = await fse.readFile(file, 'utf8');
        const cssAssetPath = `/${path.relative(exportDir, file).split(path.sep).join('/')}`;
        const rewritten = rewriteCssUrls(css, undefined, cssAssetPath, onAsset);
        if (rewritten !== css)
            await fse.writeFile(file, rewritten, 'utf8');
    }
}
export async function localizeAssets(exportDir, fetchAsset = fetchPublicAsset) {
    const queue = [...(await collectAssetPaths(exportDir))];
    const seen = new Set(queue);
    const downloaded = [];
    const failed = [];
    const enqueue = (assetPath) => {
        if (seen.has(assetPath))
            return;
        seen.add(assetPath);
        queue.push(assetPath);
    };
    await localizeStylesheets(exportDir, enqueue);
    const localize = async (assetPath) => {
        const url = fromMintExportAssetPath(assetPath);
        const outputPath = resolveOutputPath(exportDir, assetPath);
        if (!url || !outputPath) {
            failed.push(assetPath);
            return;
        }
        const asset = await fetchAsset(url);
        if (!asset) {
            if (!isLanguageIcon(url))
                failed.push(url);
            return;
        }
        await fse.ensureDir(path.dirname(outputPath));
        if (isCss(url, asset.contentType)) {
            const css = rewriteCssUrls(asset.body.toString('utf8'), url, assetPath, enqueue);
            await fse.writeFile(outputPath, css, 'utf8');
        }
        else {
            await fse.writeFile(outputPath, asset.body);
        }
        downloaded.push(assetPath);
    };
    const worker = async () => {
        while (queue.length > 0) {
            const assetPath = queue.shift();
            try {
                await localize(assetPath);
            }
            catch {
                failed.push(fromMintExportAssetPath(assetPath) ?? assetPath);
            }
        }
    };
    while (queue.length > 0) {
        await Promise.all(Array.from({ length: Math.min(CONCURRENCY, queue.length) }, worker));
    }
    return { downloaded, failed };
}
